+
+  writeFileSync(
+    recordPath,
+    `${JSON.stringify(
+      {
+        ...record,
+        ...(startedAt === undefined ? {} : { startedAt }),
+        ...(updatedAt === undefined ? {} : { updatedAt }),
+      },
+      null,
+      2
+    )}\n`,
+    'utf-8'
+  );
+
+  if (mtime) {
+    utimesSync(recordPath, mtime, mtime);
+  }
+
+  return recordPath;
